    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-22f1bf6b71d3a263c07ed9f82342' AND status='running' AND operation_hash='22f1bf6b71d3a263c07ed9f82342ddf7440fdf7c008beebb548844b7c25116b3' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
